package org.transittr;
import android.content.*;import java.io.*;import java.net.URLEncoder;import java.util.*;import org.json.*;
/** Small bundled route index plus the providers' public stop search; no second on-device database. */
public final class NetworkCatalog {
 public static boolean city(int city){return city==3||city==8||city==9||CityRegistry.asis(city);}
 private static CatalogStore.Item item(JSONObject r,int city,boolean stop)throws JSONException{CatalogStore.Item i=new CatalogStore.Item();i.kind=stop?1:0;i.code=r.optString(stop?"stopId":"displayRouteCode");i.name=r.optString("name",r.optString("stopName",""));i.type="Otobüs";i.lat=SourceTools.number(r,"lat");i.lon=SourceTools.number(r,"lng");String external=r.optString(stop?"stopId":"routeCode",i.code);int n;try{n=Integer.parseInt(external);}catch(Exception e){n=(external.hashCode()&0x07ffffff);}i.id=city>=1000?-((city-1000)*1000000+(n&0x7fffffff)%1000000):city*200000000+n;i.source=city==7?101:100;return i;}
 private static JSONArray routes(Context context,int city)throws IOException,JSONException{InputStream in=new java.util.zip.GZIPInputStream(context.getAssets().open("city-catalog-"+city+".dbz"));try{ByteArrayOutputStream b=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(b.size()+n>4194304)throw new IOException("Hat dizini sınırı");b.write(buf,0,n);}return new JSONObject(new String(b.toByteArray(),"UTF-8")).getJSONArray("routes");}finally{in.close();}}
 public static CatalogStore.Page page(Context context,int city,int mode,String query,int offset)throws IOException{try{CatalogStore.Page p=new CatalogStore.Page();ArrayList<CatalogStore.Item> values=new ArrayList<CatalogStore.Item>();SharedPreferences prefs=context.getSharedPreferences("MainActivity",0);JSONArray all=routes(context,city);if(city==9&&mode!=2){JSONObject live=BursaClient.search(query);JSONArray raw=live.optJSONArray(mode==1?"stations":"routes");all=new JSONArray();if(raw!=null)for(int z=0;z<raw.length();z++){JSONObject r=raw.getJSONObject(z),n=new JSONObject();n.put("routeCode",r.optString("routeNo"));n.put("displayRouteCode",r.optString("routeCode"));n.put("stopId",r.optString("stationId",r.optString("id")));n.put("name",r.optString("routeDescription",r.optString("description","")));n.put("lat",r.optString("latitude"));n.put("lng",r.optString("longitude"));all.put(n);}}p.routes=all.length();String normalized=CatalogStore.normalize(query.trim());
  if(mode==2){for(Map.Entry<String,?> e:prefs.getAll().entrySet())if(e.getKey().startsWith("network-item:")&&e.getValue() instanceof String){JSONObject r=new JSONObject((String)e.getValue());if(r.optInt("city",-1)!=city)continue;CatalogStore.Item i=item(r.getJSONObject("item"),city,r.getBoolean("stop"));if(prefs.getBoolean("fav:"+i.kind+":"+i.id,false)&&CatalogStore.normalize(i.code+" "+i.name).contains(normalized))values.add(i);}}
  else if(mode==0){for(int k=0;k<all.length();k++){CatalogStore.Item i=item(all.getJSONObject(k),city,false);if(CatalogStore.normalize(i.code+" "+i.name).contains(normalized))values.add(i);}}
  else{JSONArray stops=city==9?all:CityRegistry.asis(city)?AsisCityClient.forCity(city).searchStops(query):KentClient.get(city,"api/trip/search?keyword="+URLEncoder.encode(query,"UTF-8")).getJSONArray("stopList");for(int k=0;k<stops.length()&&k<200;k++)values.add(item(stops.getJSONObject(k),city,true));p.stops=values.size();}
  p.total=values.size();for(int k=Math.max(0,offset);k<Math.min(values.size(),offset+50);k++)p.items.add(values.get(k));return p;
 }catch(JSONException e){throw new IOException("Şehir kataloğu okunamadı");}}
 public static void remember(Context context,CatalogStore.Item i){try{int city=i.id<0?1000+(-i.id)/1000000:i.id/200000000;if(!city(city))return;JSONObject row=new JSONObject();row.put(i.kind==1?"stopId":"displayRouteCode",i.code);row.put("routeCode",i.id<0?(-i.id)%1000000:i.id-city*200000000);row.put("name",i.name);if(i.hasPosition()){row.put("lat",i.lat);row.put("lng",i.lon);}JSONObject value=new JSONObject();value.put("city",city);value.put("stop",i.kind==1);value.put("item",row);context.getSharedPreferences("MainActivity",0).edit().putString("network-item:"+i.kind+":"+i.id,value.toString()).commit();}catch(JSONException ignored){}}
 public static CatalogStore.Item stop(Context context,int city,String code)throws IOException{try{if(city==9){JourneyData.Station st=BursaClient.stop(code);if(st==null)return null;JSONObject n=new JSONObject();n.put("stopId",st.code);n.put("name",st.name);n.put("lat",st.lat);n.put("lng",st.lon);return item(n,city,true);}JSONArray rows=CityRegistry.asis(city)?AsisCityClient.forCity(city).searchStops(code):KentClient.get(city,"api/trip/search?keyword="+URLEncoder.encode(code,"UTF-8")).getJSONArray("stopList");for(int k=0;k<rows.length();k++)if(code.equals(rows.getJSONObject(k).optString("stopId")))return item(rows.getJSONObject(k),city,true);return null;}catch(JSONException e){throw new IOException("Durak kaydı okunamadı");}}
 public static CatalogStore.Page nearby(Context context,int city,double lat,double lon)throws IOException{if(Double.isNaN(lat)||Double.isNaN(lon)||lat<35||lat>43||lon<25||lon>45)throw new IOException("Geçerli Türkiye koordinatı gir");try{CatalogStore.Page p=new CatalogStore.Page();JSONArray rows=city==9?BursaClient.nearby(lat,lon):CityRegistry.asis(city)?AsisCityClient.forCity(city).searchStops(""):KentClient.get(city,"api/stop/closest?lat="+lat+"&lng="+lon).getJSONArray("busStopList");for(int k=0;k<rows.length()&&k<10000;k++){CatalogStore.Item i=item(rows.getJSONObject(k),city,true);if(!i.hasPosition())continue;double r=Math.PI/180,x=Math.sin((i.lat-lat)*r/2),y=Math.sin((i.lon-lon)*r/2),h=x*x+Math.cos(lat*r)*Math.cos(i.lat*r)*y*y;i.distance=12742000*Math.asin(Math.sqrt(Math.min(1,h)));if(i.distance<=2000)p.items.add(i);}Collections.sort(p.items,new Comparator<CatalogStore.Item>(){public int compare(CatalogStore.Item a,CatalogStore.Item b){return Double.compare(a.distance,b.distance);}});p.total=p.items.size();p.stops=p.total;p.routes=routes(context,city).length();while(p.items.size()>50)p.items.remove(p.items.size()-1);return p;}catch(JSONException e){throw new IOException("Yakın duraklar okunamadı");}}
}
